// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Have alice call sudicideAnyone()
        vm.prank(address(0x1234));
        // We need to capture whether the call reverts or succeeds
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        // In the correct version, the require fails → revert → ok == false, address(c).balance stays 1 ether
        // In the buggy version, selfdestruct executes → ok == true, address(c).balance becomes 0
        // We assert that the contract still has its ether: this holds for reference, breaks for mutant
        assertTrue(address(c).balance == 1 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        // Reference would revert; buggy version selfdestructs.
        // We wrap in try/catch to capture whether it reverts.
        bool success;
        try c.sudicideAnyone() { success = true; } catch { success = false; }
        // For reference: revert => success == false, contract alive => owner != address(0).
        // For buggy: selfdestruct => success == true, then contract dead => owner address becomes 0.
        assertTrue(!success || c.smartfix_owner() == address(0), "Reference reverts, buggy destroys");
    }
}
